<div class="top"><h1>Équipe et rôles</h1></div>
<div class="card"><h2>Rôles</h2><ul style="list-style:disc;padding-left:20px"><li><b>admin</b> : accès complet (réglages, équipe, catalogue, commandes…).</li><li><b>manager</b> : catalogue, commandes, devis, clients, marketing, contenu, livraison.</li><li><b>staff</b> : commandes et devis uniquement.</li></ul></div>
<div class="card"><h2>Membres</h2><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Membre</th><th>Rôle</th><th>Actif</th><th>Nouveau mot de passe</th><th></th></tr></thead><tbody><?php foreach ($rows as $u): $me = $u['id'] == user()['id']; ?><tr><form method="post" action="/admin/utilisateurs/<?= (int) $u['id'] ?>"><?= csrf_field() ?><td><b><?= e($u['name'] ?: '—') ?></b><br><small class="muted"><?= e($u['email']) ?></small></td><td><select name="role" <?= $me ? 'disabled' : '' ?>><?= select_opts(array_combine(array_keys(PERMS), array_keys(PERMS)), $u['role']) ?></select></td><td><input type="checkbox" name="active" value="1" <?= $u['active'] ? 'checked' : '' ?> <?= $me ? 'disabled' : '' ?>></td><td><input type="password" name="password" placeholder="Laisser vide" autocomplete="new-password" <?= $me ? 'disabled' : '' ?>></td><td><?= $me ? '<small class="muted">vous</small>' : '<button class="btn btn-p btn-sm">OK</button>' ?></td></form></tr><?php endforeach; ?></tbody></table></div></div>
<div class="card"><h2>Ajouter un membre</h2><form method="post" action="/admin/utilisateurs"><?= csrf_field() ?><div class="row2"><?= fld('text', 'name', 'Nom') ?><?= fld('email', 'email', 'E-mail', '', ['req' => 1]) ?></div><div class="row2"><?= fld('select', 'role', 'Rôle', 'staff', ['opts' => array_combine(array_keys(PERMS), array_keys(PERMS))]) ?><?= fld('password', 'password', 'Mot de passe (10 caractères minimum)', '', ['req' => 1]) ?></div><button class="btn btn-p">Ajouter</button></form></div>
